// Hard policy for phone push only. Logging keeps running on its own branch.
const now = Date.now();
const hour = Number(new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Europe/Oslo', hour: '2-digit', hourCycle: 'h23'
}).format(new Date(now)));
// Never queue or backfill quiet-hour messages; dashboard/log retains the event.
if (hour >= 23 || hour < 6) return [];
const state = $getWorkflowStaticData('global');
// New-device alerts (NetAlertX) have their own limit so noisy alerts cannot starve them.
const raw = JSON.stringify(($json && $json.body) || {});
const isNewDevice = /new device|ny enhet/i.test(raw);
if (isNewDevice) {
  const lastNew = Number(state.last_newdevice_push_at || 0);
  if (now - lastNew < 10 * 60 * 1000) return [];
  state.last_newdevice_push_at = now;
  return items;
}
const last = Number(state.last_phone_push_at || 0);
// Global ceiling for everything else: max one phone notification per rolling 60 minutes.
if (now - last < 60 * 60 * 1000) return [];
state.last_phone_push_at = now;
return items;

